"use strict";const e=require("../utils/request.js");exports.fetchInviteInfo=function(){return e.http.get("/invite",{noLedger:!0})},exports.fetchInviteQrCode=function(){return e.http.get("/invite/qrcode",{noLedger:!0})},exports.fetchInvitees=function(t=0,n=20){return e.http.get(`/invite/invitees?page=${t}&size=${n}`,{noLedger:!0})},exports.fetchInviterBrief=function(t){return e.http.get(`/invite/inviter?code=${encodeURIComponent(t)}`,{auth:!1,noLedger:!0})};
